import androidx.compose.ui.graphics.PathFillType
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.PathParser
import androidx.compose.ui.unit.dp

/**
 * Єдиний набір системних іконок застосунку — Material Symbols **Rounded**, контурні (Fill 0), вага
 * 300 (тонший контур, ніж стандартні 400 у `androidx.compose.material.icons`, де ні вага, ні
 * заокруглення не налаштовуються). Path — 1:1 з офіційних SVG (fonts.gstatic.com,
 * `materialsymbolsrounded/<назва>/wght300/24px.svg`, viewBox 0 -960 960 960 — тому група зсунута на
 * 960 по Y). Колір задає tint. Позначені `autoMirror` дзеркаляться в RTL.
 *
 * Нові системні іконки додавати сюди (той самий URL з іншою назвою), а не з `Icons.*`. Не сюди
 * належать іконки, що прийшли з Figma як готові SVG (`TeperaIcons`, `ic_widget*`, `ic_perm_*`).
 */
private fun symbol(name: String, path: String, autoMirror: Boolean = false): ImageVector =
    ImageVector.Builder(
        name = "Symbol$name",
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 960f,
        viewportHeight = 960f,
        autoMirror = autoMirror
    ).addGroup(translationY = 960f).addPath(
        pathData = PathParser().parsePathString(path).toNodes(),
        fill = SolidColor(Color.Black),
        pathFillType = PathFillType.NonZero
    ).clearGroup().build()

